import re
x=open('unpacked_m/word/document.xml',encoding='utf-8').read()
paras=re.findall(r'<w:p [^>]*>.*?</w:p>',x,re.S)
def txt(p): return ''.join(re.findall(r'<w:t[^>]*>(.*?)</w:t>',p,re.S))
body=[]
for i,p in enumerate(paras):
    t=txt(p)
    body.append((i,t))
# find references heading index
for i,t in body:
    if t.strip()=='References':
        refstart=i
print('refstart',refstart,'total paras',len(paras))
seq=[]
for i,t in body[:refstart]:
    for m in re.finditer(r'\[([0-9,\u2013\-\s]+)\]',t):
        seq.append(m.group(1))
print(seq)
