cd . && python3 - <<'EOF'
import re
x=open('unpacked_m/word/document.xml',encoding='utf-8').read()
paras=re.findall(r'<w:p [^>]*>.*?</w:p>',x,re.S)
def txt(p): return ''.join(re.findall(r'<w:t[^>]*>(.*?)</w:t>',p,re.S))
toks={}
for i,p in enumerate(paras[:312]):
    for m in re.finditer(r'\[[^\]]*\]',txt(p)):
        toks.setdefault(m.group(0),[]).append(i)
for k,v in toks.items(): print(repr(k),v)
print('---refs count:', len(paras)-313)
for i in range(313,len(paras)):
    t=txt(paras[i])
    m=re.match(r'(\d+)\.\t',t)
    print(i, m.group(1) if m else 'NOMATCH:'+t[:60], t[:60].replace('\t','|'))
